chapter.programlisting:
typedef struct _yar_header {
    uint32_t       id;            /* ID da transação */
    uint16_t       version;       /* versão do protocolo, atualmente sempre 0 */
    uint32_t       magic_num;     /* deve ser 0x80DFEC60 */
    uint32_t       reserved;      /* reservado */
    unsigned char  provider[32];  /* requisição de quem (autenticação) */
    unsigned char  token[32];     /* token da requisição (autenticação) */
    uint32_t       body_len;      /* comprimento de todo o corpo, incluindo
                                     o identificador do empacotador */
} __attribute__ ((packed)) yar_header_t;
